    "id": "prem_rec_0032",
    "title": "O ParkFinder é uma plataforma digital des",
    "sw_nome": "O ParkFinder é uma plataforma digital des",
    "pf_nome": "Autor / Proponente (Startup conectada com a cidade)",
    "Nome_fantasia": "Startup conectada com a cidade",
