    "id": "prem_rec_0052",
    "title": "[highlight=transparent]O [/highlight][highlight=...",
    "sw_nome": "[highlight=transparent]O [/highlight][highlight=...",
    "pf_nome": "Autor / Proponente (Letramento Digital)",
