    "id": "prem_rec_0146",
    "title": "[justify][highlight=transparent]O projeto Territ...",
    "sw_nome": "[justify][highlight=transparent]O projeto Territ...",
    "pf_nome": "Autor / Proponente (Inovação ESG)",
    "Nome_fantasia": "Inovação ESG",
