    "id": "prem_rec_0147",
    "title": "[justify][highlight=transparent]O Porto Digital ...",
    "sw_nome": "[justify][highlight=transparent]O Porto Digital ...",
    "pf_nome": "Autor / Proponente (Inovação empresarial)",
    "Nome_fantasia": "Inovação empresarial",
    "Resp_nome": "Autor / Proponente (Inovação empresarial)",
    "eixo": "Inovação Empresarial",
