    "title": "parte do enfrentamento de uma das condiçõ",
    "sw_nome": "parte do enfrentamento de uma das condiçõ",
    "pf_nome": "Autor / Proponente (Deeptech destaque)",
    "Nome_fantasia": "Deeptech destaque",
    "Resp_nome": "Autor / Proponente (Deeptech destaque)",
    "eixo": "Não especificado",
